-- public.errand_do(p_world uuid, p_id integer, p_again boolean, p_kind text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.errand_do(p_world uuid, p_id integer, p_again boolean DEFAULT false, p_kind text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
declare c creature; d species_def; kind text; skill_id text; skill double precision;
        v_job record; v_it item; v_hearth placed; v_per double precision; v_tree int;
        v_vessel placed; v_k int;
begin
  select * into c from creature where world_id = p_world and id = p_id;
  select * into d from species_def where id = c.species;
  kind := coalesce(p_kind, d.gathers);
  select g.skill into skill_id from gather_def g where g.id = kind;
  skill := task_skill(c);

  if kind = 'mend' then
    v_it := damaged_in_stores(p_world, c.keeper);
    if v_it.id is null then return false; end if;
    if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.2); end if;
    -- The same bargain the player's own repair makes: damage out, a little
    -- quality with it, and a better hand loses less of it.
    update item set dmg = greatest(0, dmg - (2 + skill / 12)),
        ql = greatest(1, ql - greatest(0.05, 0.6 - skill / 220))
      -- The most damaged and, at a stage, the next most damaged after it, its stage's number in the one go (`stage_loads`).
      where id in (select i.id from item i join crate cr on cr.world_id = i.world_id and cr.id = i.crate
                    where i.world_id = p_world and i.holder = 'crate' and i.dmg > 1 and not unrestored(i.def) and not unmendable(i.def)
                      and on_home_deed(p_world, c.keeper, cr.x, cr.y)
                    order by i.dmg desc, i.id limit stage_loads(c));
    return true;

  elsif kind = 'hod' then
    if c.carrying is null then return false; end if;
    -- Whatever on the tile it walked to wants what it is carrying, and in it goes as a builder's piece does.
    select * into v_job from hod_needing(p_world, c.work_x, c.work_y, 0, c.carrying->>'def', c.keeper);
    if v_job.item is null or v_job.item is distinct from c.carrying->>'def' then
      -- Nothing within reach wants it (`errand_step`): into the store it walked to, or the nearest with room.
      if p_again then return false; end if;
      select * into v_job from my_deed(p_world, c.keeper) md where md.world_id is not null;
      if not found then return false; end if;
      if (select h.item from hod_needing(p_world, v_job.x, v_job.y, work_range(c), c.carrying->>'def', c.keeper) h) is not null then
        return false;
      end if;
      perform private.worker_put_back(p_world, c, c.carrying->>'def', coalesce((c.carrying->>'count')::int, 1),
                         (c.carrying->>'ql')::double precision, c.work_x, c.work_y, c.carrying->>'extra');
      update creature set carrying = null where world_id = p_world and id = p_id;
      return true;
    end if;
    if not hod_fit(p_world, v_job.kind, v_job.level, v_job.dir, v_job.x, v_job.y, v_job.ref, v_job.n, v_job.item) then
      return false;
    end if;
    -- And every other piece it carries that the work still wants, in the one go; any over go on to the next work.
    v_k := 1;
    while v_k < coalesce((c.carrying->>'count')::int, 1)
      and hod_fit(p_world, v_job.kind, v_job.level, v_job.dir, v_job.x, v_job.y, v_job.ref, v_job.n, v_job.item) loop
      v_k := v_k + 1;
    end loop;
    update creature set carrying = load_less(carrying, v_k) where world_id = p_world and id = p_id;
    if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
    return true;

  elsif kind = 'stoke' then
    -- Empty-handed or holding ore, at a stage that charges smelters: the smelter worker's go.
    if c.carrying is null or fuel_value(c.carrying->>'def') is null then
      if stage_of(c) >= stoke_smelts_at() then return errand_do(p_world, p_id, p_again, 'smelt'); end if;
      if c.carrying is null then return false; end if;
    end if;
    v_per := fuel_value(c.carrying->>'def');
    v_hearth := stoke_hearth(p_world, c, c.carrying->>'def', c.work_x, c.work_y, 0, false);
    if v_hearth.id is null or v_per is null then
      -- No hearth here with room for a piece of it: into the store it walked to, or the nearest with room. A load
      -- carried back, not made (`private.worker_put_back`).
      perform private.worker_put_back(p_world, c, c.carrying->>'def', coalesce((c.carrying->>'count')::int, 1),
                         coalesce((c.carrying->>'ql')::double precision, 20), c.work_x, c.work_y, c.carrying->>'extra');
      update creature set carrying = null where world_id = p_world and id = p_id;
      return true;
    end if;
    perform placed_settle(v_hearth.id);
    select * into v_hearth from placed where id = v_hearth.id;
    -- Whole pieces that fit, and no more; the rest stay in its arms for the next hearth or the stores (`errand_step`).
    v_k := least(coalesce((c.carrying->>'count')::int, 1), floor((stoke_room(v_hearth) - placed_fuel(v_hearth)) / v_per)::int);
    if v_k < 1 then return false; end if;
    -- Fed, and lit if it had gone out; a brazier lights itself after dark (`brazier_sweep`).
    update placed set fuel = placed_fuel(placed) + v_per * v_k,
        ash = placed_ash(placed), lit = lit or not is_brazier(placed), since = now()
      where id = v_hearth.id;
    update creature set carrying = load_less(carrying, v_k) where world_id = p_world and id = p_id;
    if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.2); end if;
    return true;

  elsif kind = 'water' then
    if c.carrying->>'def' = 'water_bucket' then
      -- Pouring it in. Whichever barrel it walked to, if it still has room.
      -- Aliased, and not for tidiness: `kind` is a local in this function and
      -- a column of `placed`, and an unaliased table makes it ambiguous. That
      -- is the sixth time this class has bitten, and the first caught by
      -- running rather than by reading.
      select p2.* into v_vessel from placed p2 where p2.world_id = p_world and p2.kind = 'furniture'
        and p2.x = c.work_x and p2.y = c.work_y and holds_liquid(p2) and not is_well(p2)
        limit 1;
      if v_vessel.id is null then return false; end if;
      v_k := greatest(1, least(coalesce((c.carrying->>'count')::int, 1),
                               ceil((liquid_capacity(v_vessel) - placed_litres(v_vessel)) / bucket_litres())::int));
      update placed set litres = least(liquid_capacity(v_vessel),
                                       placed_litres(v_vessel) + v_k * bucket_litres()),
          liquid = 'water', since = now()
        where id = v_vessel.id;
      update creature set carrying = load_less(carrying, v_k) where world_id = p_world and id = p_id;
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.2); end if;
      return true;
    end if;
    -- Filling it. A well is drawn down by what is taken; a shore is not.
    select p2.* into v_vessel from placed p2 where p2.world_id = p_world and p2.kind = 'furniture'
      and p2.x = c.work_x and p2.y = c.work_y and is_well(p2) limit 1;
    v_k := fill_buckets(p_world, c);
    if v_vessel.id is not null and not draw_from(v_vessel.id, v_k * bucket_litres()) then return false; end if;
    if v_vessel.id is null and not has_water(p_world, c.work_x, c.work_y) then return false; end if;
    update creature set carrying = jsonb_build_object('def', 'water_bucket', 'count', v_k, 'ql', 40)
      where world_id = p_world and id = p_id;
    return true;

  elsif kind = 'prospect' then
    if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.22); end if;
    -- The radius grows with what it knows, the same way a player's does, and
    -- what it finds is lit for its keeper: the beast cannot read a map.
    perform read_ground(p_world, p_id, c.work_x, c.work_y, 2 + floor(skill / 20)::int);
    /*
     * And it moves on.
     *
     * `unread_ground` hashes its sixty guesses off the creature and its leg
     * number, which is how everything out here stays the same when it is
     * replayed. A deed worker never touches its leg, though — nothing in the
     * round trip needs one — so the hash was constant and the prospector
     * walked to the same square forty times, learning a great deal about one
     * patch of grass. A reading is a leg, so it counts as one.
     */
    update creature set leg = leg + 1 where world_id = p_world and id = p_id;
    return true;

  elsif kind in ('groom', 'dairy', 'heal') then
    declare o creature; od species_def; need text[]; v_top double precision; v_yield text; v_n int; v_ql double precision;
    begin
      o := herd_target(p_world, c, kind, c.work_x + 0.5, c.work_y + 0.5);
      need := case when o.id is not null then herd_need(kind, o) end;
      -- Put back what it has no use for, at the store it walked to.
      if c.carrying is not null and (o.id is null or need is null or not (c.carrying->>'def' = any(need))) then
        if p_again then return false; end if;
        perform private.worker_put_back(p_world, c, c.carrying->>'def', (c.carrying->>'count')::int, (c.carrying->>'ql')::double precision,
                           c.work_x, c.work_y, c.carrying->>'extra');
        update creature set carrying = null where world_id = p_world and id = p_id;
        return true;
      end if;
      if o.id is null then return false; end if;
      -- At the store, for the bucket or the dressing.
      if need is not null and c.carrying is null then
        if p_again then return false; end if;
        update creature set carrying = take_some_stored(p_world, c.keeper, need, stage_loads(c), c.work_x, c.work_y)
         where world_id = p_world and id = p_id;
        return true;
      end if;
      -- Beside it, or it has gone off and the next step will find it again.
      if sqrt((creature_x(o) - c.to_x) ^ 2 + (creature_y(o) - c.to_y) ^ 2) > 3 then return false; end if;
      select * into od from species_def where id = o.species;
      v_top := max_health(o);
      if kind = 'groom' then
        -- As a keeper of its skill with a brush as good (`groom_gain`), and the small hurts seen to with it.
        update creature set care = least(1, care + groom_gain(skill, skill)),
               health = least(v_top, health + v_top * groom_heal())
         where world_id = p_world and id = o.id;
        if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      elsif kind = 'dairy' then
        if milker(od) then
          -- A bucket off it, as the keeper's own milking fills one (`milk_go`).
          perform worker_put(p_world, c, 'milk_bucket', 1, greatest(1, least(100, 20 + o.fleece * 40 + o.hunger * 30)),
                             floor(creature_x(o))::int, floor(creature_y(o))::int);
          update creature set carrying = load_less(carrying) where world_id = p_world and id = p_id;
        else
          -- A full fleece is three, a full crop of feathers six, and quality follows what was there.
          v_yield := coalesce(od.shear_yield, 'wool');
          v_n := greatest(1, round(o.fleece * case when v_yield = 'wool' then 3 else 6 end)::int)
            -- And its line's own third-stage wool (`perk_n`).
            + perk_n(o, 'wool')::int;
          v_ql := greatest(1, least(100, 15 + o.fleece * 45 + skill * 0.4));
          perform worker_put(p_world, c, v_yield, v_n, v_ql, floor(creature_x(o))::int, floor(creature_y(o))::int);
        end if;
        update creature set fleece = 0 where world_id = p_world and id = o.id;
        perform beast_learns(p_world, o.id, 'tended');
        if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      else
        -- A dressing's share of a life (`heal_amount`), and the bleeding stopped.
        update creature set health = least(v_top, health + v_top * heal_amount(skill, coalesce((c.carrying->>'ql')::double precision, 1))),
               bleed_until = null, bleed_rate = null
         where world_id = p_world and id = o.id;
        update creature set carrying = load_less(carrying) where world_id = p_world and id = p_id;
        if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      end if;
      return true;
    end;

  elsif kind in ('tan', 'mill', 'saw', 'chisel', 'brick', 'fletch', 'concrete', 'mortar', 'timber', 'shaft', 'bandage', 'cheese') then
    -- A recipe worked at the stores: its inputs out of them, and what it makes back in, with what the recipe stamps on it
    -- (a healing cover's herb).
    declare v_r record; r recipe; ri record; v_i int;
    begin
      select * into v_r from recipe_in_stores(p_world, c.keeper, tend_recipes(kind));
      if v_r.rid is null then return false; end if;
      select * into r from recipe where id = v_r.rid;
      -- Round its keeper, only with room in storage in reach for what it makes.
      if c.around is not null and not around_room(p_world, c, r.id) then return false; end if;
      for ri in select * from recipe_input where recipe = r.id order by ord loop
        if ri.litres is not null then perform take_litres_stored(p_world, c.keeper, ri.item, ri.litres);
        else for v_i in 1..ri.count loop perform take_one_stored(p_world, c.keeper, array[ri.item], c.work_x, c.work_y); end loop; end if;
      end loop;
      perform worker_put(p_world, c, r.result, r.count + perk_n(c, 'more')::int, worker_made_ql(c, skill), c.work_x, c.work_y, r.extra);
      for ri in select * from recipe_gives where recipe = r.id and recipe_gives.kind = 'return' loop
        perform private.worker_put_back(p_world, c, ri.item, ri.count, 40, c.work_x, c.work_y);
      end loop;
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      return true;
    end;

  elsif kind = 'lamp' then
    declare v_p placed; v_want text; v_hold boolean := coalesce(c.carrying->>'def' = 'candle', false);
    begin
      select * into v_p from placed p where p.world_id = p_world and p.kind = 'furniture' and lamp_kind(p.sub) is not null
        and p.x = c.work_x and p.y = c.work_y and on_home_deed(p_world, c.keeper, p.x, p.y) order by p.id limit 1;
      v_want := case when v_p.id is not null then lamp_wants(p_world, v_p) end;
      if v_want is not null and (v_want <> 'candle' or v_hold) then
        if v_want = 'candle' then
          -- A candle in it, as a person sets one (`candle_burn`), and lit if it is dark.
          update placed set fuel = round(candle_burn((state->'lamp'->>'ql')::double precision)), lit = is_night(p_world), since = now()
           where id = v_p.id;
          update creature set carrying = load_less(carrying) where world_id = p_world and id = p_id;
        else
          update placed set fuel = placed_fuel(v_p), lit = v_want = 'light', since = now() where id = v_p.id;
        end if;
        perform land_announce(p_world, v_p.x, v_p.y);
        if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.2); end if;
        return true;
      end if;
      if c.carrying is not null and not v_hold then
        perform private.worker_put_back(p_world, c, c.carrying->>'def', (c.carrying->>'count')::int, (c.carrying->>'ql')::double precision,
                           c.work_x, c.work_y, c.carrying->>'extra');
        update creature set carrying = null where world_id = p_world and id = p_id;
        return true;
      end if;
      if not v_hold then
        update creature set carrying = take_some_stored(p_world, c.keeper, array['candle'], stage_loads(c), c.work_x, c.work_y)
         where world_id = p_world and id = p_id;
        return true;
      end if;
      return false;
    end;

  elsif kind in ('smelt', 'kiln') then
    declare v_p placed; v_fits text[] := furnace_fits(kind); v_hold boolean := coalesce(c.carrying->>'def' = any(furnace_fits(kind)), false);
            v_jobs jsonb; v_one jsonb; v_n int; v_secs double precision; v_metal metal_def; v_i int; v_makes text; v_room int;
            v_furnace text := case when kind = 'smelt' then 'smelter' else 'kiln' end;
    begin
      select p.* into v_p from placed p where p.world_id = p_world and p.kind = v_furnace
        and p.x = c.work_x and p.y = c.work_y and on_home_deed(p_world, c.keeper, p.x, p.y) order by p.id limit 1;
      if v_p.id is not null then
        perform furnace_settle(p_world, v_p.id);
        select * into v_p from placed where id = v_p.id;
        -- What it has made, into the stores.
        if c.carrying is null and jsonb_array_length(furnace_output(v_p)) > 0 then
          for v_one in select * from jsonb_array_elements(furnace_output(v_p)) loop
            perform worker_put(p_world, c, v_one->>'def', (v_one->>'count')::int, (v_one->>'ql')::double precision,
                               v_p.x, v_p.y, v_one->>'extra', v_one->>'piece');
          end loop;
          update placed set state = jsonb_set(state, '{output}', '[]'::jsonb) where id = v_p.id;
          if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
          return true;
        end if;
        -- What it carries, in: a job to a piece, as a person's charging makes one (`smelt_ore`, `load_kiln`).
        v_jobs := furnace_jobs(v_p);
        v_room := furnace_capacity(v_p) - jsonb_array_length(v_jobs);
        if v_hold and v_room > 0 then
          v_n := least((c.carrying->>'count')::int, v_room);
          if kind = 'smelt' then
            v_metal := metal_by_ore(c.carrying->>'def');
            v_secs := smelt_seconds(v_metal.id, (c.carrying->>'ql')::double precision, v_p.ql);
            for v_i in 1..v_n loop
              v_jobs := v_jobs || jsonb_build_object('makes', v_metal.lump, 'left', v_secs, 'total', v_secs, 'ql', (c.carrying->>'ql')::double precision);
            end loop;
          else
            v_makes := (select pd.fired from pottery_def pd where pd.unfired = c.carrying->>'def');
            v_secs := fire_seconds(c.carrying->>'def', v_p.ql);
            for v_i in 1..v_n loop
              v_jobs := v_jobs || jsonb_build_object('makes', v_makes, 'left', v_secs, 'total', v_secs,
                'ql', fired_ql((c.carrying->>'ql')::double precision, v_p.ql));
            end loop;
          end if;
          update placed set state = jsonb_set(coalesce(state, '{}'::jsonb), '{jobs}', v_jobs) where id = v_p.id;
          update creature set carrying = case when (carrying->>'count')::int > v_n
                   then jsonb_set(carrying, '{count}', to_jsonb((carrying->>'count')::int - v_n)) end
           where world_id = p_world and id = p_id;
          if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
          return true;
        end if;
      end if;
      if c.carrying is not null and not v_hold then
        perform private.worker_put_back(p_world, c, c.carrying->>'def', (c.carrying->>'count')::int, (c.carrying->>'ql')::double precision,
                           c.work_x, c.work_y, c.carrying->>'extra');
        update creature set carrying = null where world_id = p_world and id = p_id;
        return true;
      end if;
      -- At a store: as much as the nearest furnace with room will take.
      if not v_hold then
        v_p := furnace_target(p_world, c, kind, false, c.work_x + 0.5, c.work_y + 0.5);
        if v_p.id is null then return false; end if;
        update creature set carrying = take_some_stored(p_world, c.keeper, v_fits,
                 furnace_capacity(v_p) - jsonb_array_length(furnace_jobs(v_p)), c.work_x, c.work_y)
         where world_id = p_world and id = p_id;
        return true;
      end if;
      return false;
    end;

  elsif kind = 'ash' then
    declare v_p placed; v_whole int; v_r record; r recipe; ri record; v_i int;
    begin
      select p.* into v_p from placed p where p.world_id = p_world and (p.kind in ('campfire', 'smelter', 'kiln') or is_oven(p))
        and p.x = c.work_x and p.y = c.work_y and floor(placed_ash(p)) >= 1 and on_home_deed(p_world, c.keeper, p.x, p.y)
        order by p.id limit 1;
      if v_p.id is not null then
        -- Every whole ash in it, as a person's rake takes them (`perform_fire`).
        perform placed_settle(v_p.id);
        select * into v_p from placed where id = v_p.id;
        v_whole := floor(v_p.ash)::int;
        if v_whole < 1 then return false; end if;
        update placed set ash = ash - v_whole where id = v_p.id;
        perform worker_put(p_world, c, 'ash', v_whole, 20, v_p.x, v_p.y);
        if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.2); end if;
        return true;
      end if;
      -- Nothing to rake here: lye out of the stores.
      select * into v_r from recipe_in_stores(p_world, c.keeper, tend_recipes('ash'));
      if v_r.rid is null then return false; end if;
      select * into r from recipe where id = v_r.rid;
      for ri in select * from recipe_input where recipe = r.id order by ord loop
        if ri.litres is not null then perform take_litres_stored(p_world, c.keeper, ri.item, ri.litres);
        else for v_i in 1..ri.count loop perform take_one_stored(p_world, c.keeper, array[ri.item], c.work_x, c.work_y); end loop; end if;
      end loop;
      perform worker_put(p_world, c, r.result, r.count, worker_made_ql(c, skill), c.work_x, c.work_y);
      for ri in select * from recipe_gives where recipe = r.id and recipe_gives.kind = 'return' loop
        perform private.worker_put_back(p_world, c, ri.item, ri.count, 40, c.work_x, c.work_y);
      end loop;
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      return true;
    end;

  elsif kind = 'brew' then
    -- A brew set going as a person sets one (`start_brew`): never spoiled, at the makings' quality and its brewing, half and half.
    declare v_b brew_def; v_p placed; v_i int; v_ql double precision := 0; v_one jsonb;
    begin
      v_b := brew_in_stores(p_world, c.keeper);
      if v_b.id is null then return false; end if;
      select p.* into v_p from placed p where p.world_id = p_world and p.kind = 'furniture' and p.x = c.work_x and p.y = c.work_y
        and holds_liquid(p) and not is_well(p) and not is_working(p) and coalesce(placed_liquid(p), '') = 'water'
        and placed_litres(p) >= v_b.litres and on_home_deed(p_world, c.keeper, p.x, p.y) order by p.id limit 1;
      if v_p.id is null then return false; end if;
      for v_i in 1..v_b.count loop
        v_one := take_one_stored(p_world, c.keeper, array[v_b.input], c.work_x, c.work_y);
        v_ql := v_ql + coalesce((v_one->>'ql')::double precision, 20);
      end loop;
      update placed set litres = v_b.litres, liquid = v_b.id, ferment = private.brew_seconds(v_p, v_b), since = now(), knack = null,
             ql = greatest(1, least(100, (v_ql / v_b.count + skill) / 2))
       where id = v_p.id;
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.3); end if;
      return true;
    end;

  elsif kind = 'cook' then
    -- At a lit campfire or oven of yours, the first recipe the stores hold the makings of, cooked and put in the stores.
    declare v_r record; r recipe; ri record; v_i int;
    begin
      if not exists (select 1 from placed p where p.world_id = p_world and (p.kind = 'campfire' or is_oven(p)) and placed_lit(p)
                       and sqrt((p.cx - c.to_x) ^ 2 + (p.cy - c.to_y) ^ 2) <= 3) then return false; end if;
      select * into v_r from recipe_in_stores(p_world, c.keeper, tend_recipes('cook'));
      if v_r.rid is null then return false; end if;
      select * into r from recipe where id = v_r.rid;
      for ri in select * from recipe_input where recipe = r.id order by ord loop
        if ri.litres is not null then perform take_litres_stored(p_world, c.keeper, ri.item, ri.litres);
        else for v_i in 1..ri.count loop perform take_one_stored(p_world, c.keeper, array[ri.item]); end loop; end if;
      end loop;
      perform worker_put(p_world, c, r.result, r.count, worker_made_ql(c, skill), c.work_x, c.work_y);
      for ri in select * from recipe_gives where recipe = r.id and recipe_gives.kind = 'return' loop
        perform private.worker_put_back(p_world, c, ri.item, ri.count, 40, c.work_x, c.work_y);
      end loop;
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      return true;
    end;

  elsif kind = 'restore' then
    -- Every piece of the relic out of the stores, the least damaged of each, and the relic back in at what they were worth.
    declare v_r record; rd relic_def; v_part int; v_it item; v_worth double precision := 0;
    begin
      select * into v_r from relic_in_stores(p_world, c.keeper);
      if v_r.name is null then return false; end if;
      select * into rd from relic_def where name = v_r.name;
      for v_part in 1..rd.parts loop
        select (s.it).* into v_it from deed_store_items(p_world, c.keeper) s
         where (s.it).def = 'fragment' and not coalesce((s.it).locked, false)
           and lower(fragment_relic((s.it).extra)) = lower(rd.name) and fragment_part((s.it).extra) = v_part
         order by (s.it).dmg, (s.it).id limit 1;
        if v_it.id is null then return false; end if;
        v_worth := v_worth + v_it.ql * (1 - v_it.dmg / 200.0);
        if not item_take_units(v_it, 1) then return false; end if;
      end loop;
      perform worker_put(p_world, c, rd.result, 1, greatest(1, least(100, v_worth / rd.parts * (0.72 + skill / 260))), c.work_x, c.work_y);
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.3); end if;
      return true;
    end;

  elsif kind = 'patch' then
    -- A planter: harvested when ripe, tended when it wants it, sown when empty, as a person's hands do each.
    declare v_p placed; v_c planter_crop; cd crop_def; v_yld int[]; v_ql double precision; v_made double precision;
            v_hold boolean := coalesce(c.carrying->>'def' = any(array(select x.seed from crop_def x)), false);
    begin
      select p.* into v_p from placed p where p.world_id = p_world and p.kind = 'furniture' and is_planter(p.sub)
        and p.x = c.work_x and p.y = c.work_y and on_home_deed(p_world, c.keeper, p.x, p.y) order by p.id limit 1;
      if v_p.id is not null then
        perform planter_settle(p_world, v_p.id);
        select * into v_c from planter_crop where placed = v_p.id;
        v_made := worker_made_ql(c, skill);
        if v_c.placed is null and v_hold then
          select * into cd from crop_def where seed = c.carrying->>'def';
          insert into planter_crop (placed, world_id, id, ql, sown_by, pace)
          values (v_p.id, p_world, cd.id, (c.carrying->>'ql')::real, c.keeper, 1)
          on conflict (placed) do update set id = excluded.id, stage = 0, stage_at = now(),
            tended = 0, tended_now = false, ql = excluded.ql, sown_by = excluded.sown_by, pace = 1;
          update placed set state = coalesce(state, '{}'::jsonb) || jsonb_build_object('sown', cd.id) where id = v_p.id;
          update creature set carrying = load_less(carrying) where world_id = p_world and id = p_id;
          perform land_announce(p_world, v_p.x, v_p.y);
          if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
          return true;
        elsif v_c.placed is not null and v_c.stage >= crop_ripe() then
          select * into cd from crop_def where id = v_c.id;
          v_yld := crop_yield(v_c.tended);
          v_ql := greatest(1, least(100, (v_c.ql + v_made) / 2));
          perform worker_put(p_world, c, cd.produce, v_yld[2], v_ql, v_p.x, v_p.y);
          v_yld[1] := harvest_seeds();
          if v_yld[1] > 0 then perform worker_put(p_world, c, cd.seed, v_yld[1], v_ql, v_p.x, v_p.y); end if;
          delete from planter_crop where placed = v_p.id;
          perform land_announce(p_world, v_p.x, v_p.y);
          if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
          return true;
        elsif v_c.placed is not null and not v_c.tended_now then
          update planter_crop set tended_now = true, tended = tended + 1,
                 ql = (ql * (tended + 1) + v_made) / (tended + 2)
           where placed = v_p.id;
          if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
          return true;
        end if;
      end if;
      if c.carrying is not null and not v_hold then
        perform private.worker_put_back(p_world, c, c.carrying->>'def', (c.carrying->>'count')::int, (c.carrying->>'ql')::double precision,
                           c.work_x, c.work_y, c.carrying->>'extra');
        update creature set carrying = null where world_id = p_world and id = p_id;
        return true;
      end if;
      if not v_hold then
        update creature set carrying = take_some_stored(p_world, c.keeper, (select array_agg(x.seed) from crop_def x), stage_loads(c), c.work_x, c.work_y)
         where world_id = p_world and id = p_id;
        return true;
      end if;
      return false;
    end;

  elsif kind = 'paper' then
    -- At a paper press of yours, the reeds and a bucket of water out of the stores, and the sheets and the bucket back in.
    declare v_r record; r recipe; ri record; v_i int;
    begin
      if c.carrying is not null then return false; end if;
      if not exists (select 1 from placed p where p.world_id = p_world and p.kind = 'furniture' and p.sub = 'paper_press'
                       and on_home_deed(p_world, c.keeper, p.x, p.y)
                       and sqrt((p.cx - c.to_x) ^ 2 + (p.cy - c.to_y) ^ 2) <= 3) then return false; end if;
      select * into v_r from recipe_in_stores(p_world, c.keeper, tend_recipes('paper'));
      if v_r.rid is null then return false; end if;
      select * into r from recipe where id = v_r.rid;
      for ri in select * from recipe_input where recipe = r.id order by ord loop
        if ri.litres is not null then perform take_litres_stored(p_world, c.keeper, ri.item, ri.litres);
        else for v_i in 1..ri.count loop perform take_one_stored(p_world, c.keeper, array[ri.item]); end loop; end if;
      end loop;
      perform worker_put(p_world, c, r.result, r.count, worker_made_ql(c, skill), c.work_x, c.work_y);
      for ri in select * from recipe_gives where recipe = r.id and recipe_gives.kind = 'return' loop
        perform private.worker_put_back(p_world, c, ri.item, ri.count, 40, c.work_x, c.work_y);
      end loop;
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      return true;
    end;

  elsif kind = 'fill' then
    declare v_well placed; v_one jsonb; v_def text := c.carrying->>'def';
    begin
      if v_def is null then
        -- An empty bucket out of the store it walked to.
        v_one := take_some_stored(p_world, c.keeper, array['bucket'], fill_buckets(p_world, c), c.work_x, c.work_y);
        if v_one is null then return false; end if;
        update creature set carrying = jsonb_build_object('def', 'bucket', 'count', v_one->'count', 'ql', v_one->'ql')
         where world_id = p_world and id = p_id;
        return true;
      end if;
      if v_def = 'bucket' then
        -- Filled where it stands, if that is water: a well is drawn down by what is taken, a shore is not.
        select p2.* into v_well from placed p2 where p2.world_id = p_world and p2.kind = 'furniture'
          and p2.x = c.work_x and p2.y = c.work_y and is_well(p2) limit 1;
        if (v_well.id is not null and draw_from(v_well.id, bucket_litres() * coalesce((c.carrying->>'count')::int, 1)))
           or (v_well.id is null and has_water(p_world, c.work_x, c.work_y)) then
          update creature set carrying = jsonb_set(carrying, '{def}', '"water_bucket"')
           where world_id = p_world and id = p_id;
          if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.2); end if;
          return true;
        end if;
      end if;
      -- Anything else in its arms goes into the stores where it stands.
      perform private.worker_put_back(p_world, c, v_def, coalesce((c.carrying->>'count')::int, 1),
                         coalesce((c.carrying->>'ql')::double precision, 40), c.work_x, c.work_y, c.carrying->>'extra');
      update creature set carrying = null where world_id = p_world and id = p_id;
      return true;
    end;

  elsif kind = 'spin' then
    -- At a spindle of yours, the fibre out of the stores and the yarn back in.
    declare v_r record; r recipe; ri record; v_i int;
    begin
      if c.carrying is not null then return false; end if;
      if not exists (select 1 from placed p where p.world_id = p_world and p.kind = 'furniture' and p.sub = 'spindle'
                       and on_home_deed(p_world, c.keeper, p.x, p.y)
                       and sqrt((p.cx - c.to_x) ^ 2 + (p.cy - c.to_y) ^ 2) <= 3) then return false; end if;
      select * into v_r from recipe_in_stores(p_world, c.keeper, tend_recipes('spin'));
      if v_r.rid is null then return false; end if;
      select * into r from recipe where id = v_r.rid;
      for ri in select * from recipe_input where recipe = r.id order by ord loop
        if ri.litres is not null then perform take_litres_stored(p_world, c.keeper, ri.item, ri.litres);
        else for v_i in 1..ri.count loop perform take_one_stored(p_world, c.keeper, array[ri.item]); end loop; end if;
      end loop;
      perform worker_put(p_world, c, r.result, r.count, worker_made_ql(c, skill), c.work_x, c.work_y);
      for ri in select * from recipe_gives where recipe = r.id and recipe_gives.kind = 'return' loop
        perform private.worker_put_back(p_world, c, ri.item, ri.count, 40, c.work_x, c.work_y);
      end loop;
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      return true;
    end;

  elsif kind in ('nail', 'ribbon') then
    -- At an anvil of yours, a lump of the first of its metals the stores hold out of them, beaten out into as many
    -- pieces as its mould's filling makes, of that metal, at its own hand's quality, and into the stores. No mould,
    -- no hammer.
    declare v_l text; v_one jsonb; v_m mould_def;
    begin
      if c.carrying is not null then return false; end if;
      if not exists (select 1 from placed p where p.world_id = p_world and p.kind = 'anvil'
                       and on_home_deed(p_world, c.keeper, p.x, p.y)
                       and sqrt((p.cx - c.to_x) ^ 2 + (p.cy - c.to_y) ^ 2) <= 3) then return false; end if;
      select u.l into v_l from unnest(smith_lumps(kind)) with ordinality u(l, o)
       where stores_count(p_world, c.keeper, u.l) > 0 order by u.o limit 1;
      if v_l is null then return false; end if;
      select * into v_m from mould_def where id = smith_mould(kind);
      if v_m.id is null then return false; end if;
      v_one := take_one_stored(p_world, c.keeper, array[v_l]);
      if v_one is null then return false; end if;
      perform worker_put(p_world, c, v_m.makes, v_m.per, worker_made_ql(c, skill), c.work_x, c.work_y,
                         (select md.name from metal_def md where md.lump = v_l));
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      return true;
    end;

  elsif kind = 'glass' then
    -- At a lit smelter of yours, charged or not, the sand out of the stores and the lumps back in, its line's third-stage
    -- lumps on each batch.
    declare v_r record; r recipe; ri record; v_i int;
    begin
      if c.carrying is not null then return false; end if;
      if not exists (select 1 from placed p where p.world_id = p_world and p.kind = 'smelter' and placed_lit(p)
                       and on_home_deed(p_world, c.keeper, p.x, p.y)
                       and sqrt((p.cx - c.to_x) ^ 2 + (p.cy - c.to_y) ^ 2) <= 3) then return false; end if;
      select * into v_r from recipe_in_stores(p_world, c.keeper, tend_recipes('glass'));
      if v_r.rid is null then return false; end if;
      select * into r from recipe where id = v_r.rid;
      for ri in select * from recipe_input where recipe = r.id order by ord loop
        if ri.litres is not null then perform take_litres_stored(p_world, c.keeper, ri.item, ri.litres);
        else for v_i in 1..ri.count loop perform take_one_stored(p_world, c.keeper, array[ri.item]); end loop; end if;
      end loop;
      perform worker_put(p_world, c, r.result, r.count + perk_n(c, 'more')::int, worker_made_ql(c, skill), c.work_x, c.work_y);
      for ri in select * from recipe_gives where recipe = r.id and recipe_gives.kind = 'return' loop
        perform worker_put(p_world, c, ri.item, ri.count, 40, c.work_x, c.work_y);
      end loop;
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      return true;
    end;

  elsif kind = 'churn' then
    -- At a butter churn of yours, the milk out of the stores and the butter and the bucket back in.
    declare v_r record; r recipe; ri record; v_i int;
    begin
      if c.carrying is not null then return false; end if;
      if not exists (select 1 from placed p where p.world_id = p_world and p.kind = 'furniture' and p.sub = 'butter_churn'
                       and on_home_deed(p_world, c.keeper, p.x, p.y)
                       and sqrt((p.cx - c.to_x) ^ 2 + (p.cy - c.to_y) ^ 2) <= 3) then return false; end if;
      select * into v_r from recipe_in_stores(p_world, c.keeper, tend_recipes('churn'));
      if v_r.rid is null then return false; end if;
      select * into r from recipe where id = v_r.rid;
      for ri in select * from recipe_input where recipe = r.id order by ord loop
        if ri.litres is not null then perform take_litres_stored(p_world, c.keeper, ri.item, ri.litres);
        else for v_i in 1..ri.count loop perform take_one_stored(p_world, c.keeper, array[ri.item]); end loop; end if;
      end loop;
      perform worker_put(p_world, c, r.result, r.count, worker_made_ql(c, skill), c.work_x, c.work_y);
      for ri in select * from recipe_gives where recipe = r.id and recipe_gives.kind = 'return' loop
        perform private.worker_put_back(p_world, c, ri.item, ri.count, 40, c.work_x, c.work_y);
      end loop;
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      return true;
    end;

  elsif kind = 'alloy' then
    -- At a lit smelter of yours, charged or not, the lumps out of the stores and the alloy back in, at the quality of
    -- the lumps by weight as your own hands mix it (`perform_craft`'s `ql_from_inputs`), its line's third-stage lumps
    -- on each batch.
    declare v_r record; r recipe; ri record; v_i int; v_one jsonb; v_w double precision;
            v_qls double precision := 0; v_wt double precision := 0; v_ql double precision;
    begin
      if c.carrying is not null then return false; end if;
      if not exists (select 1 from placed p where p.world_id = p_world and p.kind = 'smelter' and placed_lit(p)
                       and on_home_deed(p_world, c.keeper, p.x, p.y)
                       and sqrt((p.cx - c.to_x) ^ 2 + (p.cy - c.to_y) ^ 2) <= 3) then return false; end if;
      select * into v_r from recipe_in_stores(p_world, c.keeper, tend_recipes('alloy'));
      if v_r.rid is null then return false; end if;
      select * into r from recipe where id = v_r.rid;
      for ri in select * from recipe_input where recipe = r.id order by ord loop
        v_w := coalesce((select idf.weight from item_def idf where idf.id = ri.item), 1);
        if ri.litres is not null then perform take_litres_stored(p_world, c.keeper, ri.item, ri.litres);
        else
          for v_i in 1..ri.count loop
            v_one := take_one_stored(p_world, c.keeper, array[ri.item]);
            if v_one is not null then v_qls := v_qls + (v_one->>'ql')::double precision * v_w; v_wt := v_wt + v_w; end if;
          end loop;
        end if;
      end loop;
      v_ql := case when r.ql_from_inputs
                   then least(100, greatest(1, (case when v_wt > 0 then v_qls / v_wt else 1 end) * (alloy_ql_base() + skill / alloy_ql_span())
                                              * beast_mul(c, 'yield')))
                   else worker_made_ql(c, skill) end;
      perform worker_put(p_world, c, r.result, r.count + perk_n(c, 'more')::int, v_ql, c.work_x, c.work_y);
      for ri in select * from recipe_gives where recipe = r.id and recipe_gives.kind = 'return' loop
        perform private.worker_put_back(p_world, c, ri.item, ri.count, 40, c.work_x, c.work_y);
      end loop;
      if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
      return true;
    end;

  elsif kind = 'vine' then
    -- A trellis of yours with no vine, at ground level on soil: a grape cutting planted at its foot, as your own hands
    -- plant one (`perform_vine`). At the stores: its stage's cuttings into its arms.
    declare v_p placed; v_hold boolean := coalesce(c.carrying->>'def' = grape_cutting_item(), false);
    begin
      select p.* into v_p from placed p where p.world_id = p_world and p.kind = 'furniture' and p.sub = vine_kind()
        and p.x = c.work_x and p.y = c.work_y and p.vine_at is null and coalesce(p.level, 0) = 0
        and vine_soil(land_tile(p_world, p.x::int, p.y::int)) and on_home_deed(p_world, c.keeper, p.x, p.y)
       order by p.id limit 1;
      if v_p.id is not null and v_hold then
        update placed set vine_at = vine_now(), picked_at = null where id = v_p.id;
        update creature set carrying = load_less(carrying) where world_id = p_world and id = p_id;
        perform land_announce(p_world, v_p.x::int, v_p.y::int);
        if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
        return true;
      end if;
      if c.carrying is not null and not v_hold then
        perform private.worker_put_back(p_world, c, c.carrying->>'def', (c.carrying->>'count')::int, (c.carrying->>'ql')::double precision,
                           c.work_x, c.work_y, c.carrying->>'extra');
        update creature set carrying = null where world_id = p_world and id = p_id;
        return true;
      end if;
      if not v_hold then
        update creature set carrying = take_some_stored(p_world, c.keeper, array[grape_cutting_item()], stage_loads(c), c.work_x, c.work_y)
         where world_id = p_world and id = p_id;
        return true;
      end if;
      return false;
    end;

  elsif kind = 'lily' then
    -- Water on your settlement a water plant takes: a water lily root or lotus seeds planted in it, as your own hands
    -- plant one (`perform_water_garden`). At the stores: its stage's roots or seeds into its arms.
    declare v_kind text; v_hold boolean := coalesce(c.carrying->>'def' = any(array(select w.from_item from water_plant_def w)), false);
    begin
      if v_hold then
        select w.id into v_kind from water_plant_def w where w.from_item = c.carrying->>'def';
        if c.work_x is null or not on_home_deed(p_world, c.keeper, c.work_x, c.work_y)
           or plant_refusal(p_world, v_kind, c.work_x, c.work_y) is not null then return false; end if;
        insert into water_plant (world_id, x, y, kind, planted_at, planted_by) values (p_world, c.work_x, c.work_y, v_kind, now(), c.keeper);
        update creature set carrying = load_less(carrying) where world_id = p_world and id = p_id;
        if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
        return true;
      end if;
      if c.carrying is not null then
        perform private.worker_put_back(p_world, c, c.carrying->>'def', (c.carrying->>'count')::int, (c.carrying->>'ql')::double precision,
                           c.work_x, c.work_y, c.carrying->>'extra');
        update creature set carrying = null where world_id = p_world and id = p_id;
        return true;
      end if;
      update creature set carrying = take_some_stored(p_world, c.keeper, array(select w.from_item from water_plant_def w order by w.id),
                                                      stage_loads(c), c.work_x, c.work_y)
       where world_id = p_world and id = p_id;
      return true;
    end;

  elsif kind = 'plant' then
    if c.carrying->>'def' is distinct from 'sprout' then return false; end if;
    if not plantable_tile(p_world, c.work_x, c.work_y) then
      update creature set carrying = null where world_id = p_world and id = p_id;
      return false;
    end if;
    v_tree := coalesce((select id from tree_def where name = c.carrying->>'extra'), 0);
    perform land_set_tile(p_world, c.work_x, c.work_y, tile_id('Tree'));
    perform land_set_data(p_world, c.work_x, c.work_y, v_tree);
    perform land_announce(p_world, c.work_x, c.work_y);
    update creature set carrying = load_less(carrying) where world_id = p_world and id = p_id;
    if not p_again then perform worker_learn(p_world, p_id, skill_id, 0.25); end if;
    return true;
  end if;
  return false;
end $function$
